# --- Cell 3: Problem 3a & 3b Intro ---
md3 = """## 3. Auto-regressive model (3a & 3b)

**Goal:** Simulate a pairwise AR model (Source X -> Target Y) oscillating at 40Hz with 100 trials and a single stimulus.
"""

# --- Cell 4: Problem 3a & 3b Code ---
code4 = """# Parameters
n_epochs = 100
n_stim = 1
ar_type = 'osc_40'

# Initialize AR Simulation
ss_1b = StimSpecAR()

# Fit model (3a: 40Hz, 3b: 100 trials, single stimulus)
ar_data_1b = ss_1b.fit(ar_type=ar_type, n_epochs=n_epochs, n_stim=n_stim)

print("Data shape:", ar_data_1b.shape)

# Plot single trial data and causal coupling (3b)
plt.figure(figsize=(10, 8))
ss_1b.plot(cmap='bwr')
plt.show()"""

